import { loadFont as loadDisplay } from "@remotion/google-fonts/Geist";
import React, { forwardRef, useId, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

interface RingAlignProps {
  /** Word revealed in the channel once every slot lines up. */
  word?: string;
  /** Number of concentric rings. */
  rings?: number;
  accent?: string;
  /** Frames between rings locking into place. */
  stagger?: number;
  /** Radius of the ring dots, in px at 720p. */
  dotSize?: number;
  /** Solid color for the word and ring dots in place of the theme. */
  ink?: string;
  /** Solid fill in place of the toned ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the word. Load it yourself; Geist by default. */
  fontFamily?: string;
  /** Size of the rings and word, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  speed?: number;
  theme?: "dark" | "light";
}

const FIRST_LOCK = 30;
const LOCK_STEP = 8;
const BEAM_GAP = 4;
const BEAM = 14;
const TAIL_DELAY = 8;
const TAIL = 16;
const HOLD = 32;

const ringAlignLength = (rings = 6, stagger = LOCK_STEP) =>
  FIRST_LOCK + (rings - 1) * stagger + BEAM_GAP + TAIL_DELAY + TAIL + HOLD;

const LOCK = Easing.bezier(0.3, 0.55, 0.32, 1.05);
const WIPE = Easing.bezier(0.22, 1, 0.36, 1);
const TAIL_EASE = Easing.bezier(0.55, 0, 0.25, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function hash(n: number): number {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

function circle(x: number, y: number, r: number) {
  const rs = r.toFixed(2);
  const d = (2 * r).toFixed(2);
  return `M${(x - r).toFixed(1)} ${y.toFixed(1)}a${rs} ${rs} 0 1 0 ${d} 0a${rs} ${rs} 0 1 0 -${d} 0`;
}

function wrap(a: number) {
  let v = a % (Math.PI * 2);
  if (v > Math.PI) v -= Math.PI * 2;
  if (v < -Math.PI) v += Math.PI * 2;
  return v;
}

/* gradients.sh "radial-glow" palette: the beam that runs the channel, and
   the fill the word keeps once the beam has passed. */
const GLOW = ["#f3f1ff", "#9db4ff", "#5a46cb", "#1d1240"] as const;

function Grain({ opacity, light }: { opacity: number; light: boolean }) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={`${uid}-grain`}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency={0.85}
          numOctaves={2}
          seed={3}
        />
        <feColorMatrix
          type="matrix"
          values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 1 0"
        />
      </filter>
      <rect
        width="100%"
        height="100%"
        filter={`url(#${uid}-grain)`}
        opacity={opacity}
        style={{ mixBlendMode: light ? "multiply" : "screen" }}
      />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function RingAlignBase({
  word = "Aligned.",
  rings = 6,
  accent = "#3B5BFD",
  stagger = LOCK_STEP,
  dotSize = 3.1,
  ink,
  background,
  fontFamily = display,
  scale = 1,
  delay = 0,
  grain = true,
  speed = 1,
  theme = "dark",
}: RingAlignProps) {
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H } = useSceneConfig();
  const isLight = theme === "light";
  const bg = isLight ? "#F5F4F0" : "#0A0A0B";
  const fg = ink ?? (isLight ? "#141416" : "#EEEEF0");
  const u = Math.min(W, H) / 720;
  const n = Math.max(3, Math.min(9, Math.round(rings)));
  const cx = W / 2;
  const cy = H / 2;

  const band = H * 0.175;
  const pad = 9 * u;
  const rIn = H * 0.165;
  const rOut = H * 0.44;
  const dotR = dotSize * u;
  const pitch = 17 * u;

  const lastLock = FIRST_LOCK + (n - 1) * stagger;
  const beamStart = lastLock + BEAM_GAP;

  const ringPaths: { d: string; opacity: number }[] = [];
  for (let k = 0; k < n; k++) {
    // Outer ring locks first, the innermost last.
    const r = rOut - ((rOut - rIn) * k) / (n - 1);
    const count = Math.round((Math.PI * 2 * r) / pitch);
    const gap = 2 * Math.asin(Math.min(0.98, (band / 2 + pad) / r));
    const lockAt = FIRST_LOCK + k * stagger;
    const dir = k % 2 === 0 ? 1 : -1;
    const offset = dir * Math.PI * (1.35 + hash(k * 4.1) * 0.5);
    const x = Math.min(1, Math.max(0, t / lockAt));
    let rot = offset * (1 - LOCK(x));
    const since = t - lockAt;
    if (since > 0) {
      rot +=
        -dir * 0.012 * Math.sin((since / 7) * Math.PI) * Math.exp(-since / 4);
    }
    const lit = interpolate(since, [-2, 6], [0.42, 1], CLAMP);
    const segs: string[] = [];
    for (let j = 0; j < count; j++) {
      const a = (j / count) * Math.PI * 2 + rot;
      const local = wrap((j / count) * Math.PI * 2);
      const toSlot = Math.min(Math.abs(local), Math.abs(wrap(local - Math.PI)));
      if (toSlot < gap / 2) continue;
      segs.push(circle(cx + Math.cos(a) * r, cy + Math.sin(a) * r, dotR));
    }
    ringPaths.push({ d: segs.join(""), opacity: lit });
  }

  const head =
    W * WIPE(interpolate(t, [beamStart, beamStart + BEAM], [0, 1], CLAMP));
  const tail =
    W *
    TAIL_EASE(
      interpolate(
        t,
        [beamStart + TAIL_DELAY, beamStart + TAIL_DELAY + TAIL],
        [0, 1],
        CLAMP,
      ),
    );
  const fontSize = band * 0.72;
  const dot = word.endsWith(".");
  const body = dot ? word.slice(0, -1) : word;
  const [g0, g1, g2, g3] = GLOW;
  const drift = interpolate(
    t,
    [beamStart, ringAlignLength(n, stagger)],
    [0, 1],
    CLAMP,
  );
  const wordFill = ink
    ? `linear-gradient(${ink}, ${ink})`
    : isLight
      ? `linear-gradient(90deg, ${g2} ${(-10 + 20 * drift).toFixed(1)}%, ${g3} ${(45 + 10 * drift).toFixed(1)}%, ${g2} ${(110 + 10 * drift).toFixed(1)}%)`
      : `linear-gradient(90deg, ${g1} ${(-10 + 20 * drift).toFixed(1)}%, ${g0} ${(45 + 10 * drift).toFixed(1)}%, ${g1} ${(110 + 10 * drift).toFixed(1)}%)`;
  const beamFill = `linear-gradient(90deg, ${g3} 0%, ${g2} 45%, color-mix(in oklab, ${g2} 55%, ${g1}) 88%, ${g1} 98%, ${g0} 100%)`;
  const wordLayer = (fill: string, l: number, r: number) => (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: cy - band / 2,
        width: W,
        height: band,
        clipPath: `inset(0 ${(W - r).toFixed(1)}px 0 ${l.toFixed(1)}px)`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          fontFamily,
          fontWeight: 500,
          fontSize,
          letterSpacing: "-0.035em",
          lineHeight: 1.1,
          whiteSpace: "nowrap",
          paddingBottom: fontSize * 0.04,
          paddingRight: fontSize * 0.04,
          backgroundImage: fill,
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
          color: "transparent",
        }}
      >
        {body}
        {dot ? (
          <span
            style={{
              WebkitTextFillColor: fill.includes("#FFFFFF")
                ? "#FFFFFF"
                : accent,
            }}
          >
            .
          </span>
        ) : null}
      </div>
    </div>
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor:
          background === "transparent" ? undefined : (background ?? bg),
        backgroundImage:
          background !== undefined
            ? undefined
            : isLight
              ? `radial-gradient(34% 58% at 50% 50%, color-mix(in oklab, ${GLOW[1]} 16%, transparent) 0%, transparent 100%), radial-gradient(70% 70% at 50% 50%, #FBFAF7 0%, ${bg} 72%)`
              : `radial-gradient(34% 58% at 50% 50%, color-mix(in oklab, ${GLOW[2]} 22%, transparent) 0%, transparent 100%), radial-gradient(70% 70% at 50% 50%, #121215 0%, ${bg} 72%)`,
        overflow: "hidden",
      }}
    >
      <ScaleLayer scale={scale}>
        <svg
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          {ringPaths.map((p, k) => (
            <path
              key={`ring-${k.toString()}`}
              d={p.d}
              fill={fg}
              opacity={p.opacity}
            />
          ))}
        </svg>
        {tail > 0 ? wordLayer(wordFill, 0, tail) : null}
        {head > tail + 0.5 ? (
          <div
            style={{
              position: "absolute",
              left: tail,
              top: cy - band / 2,
              width: head - tail,
              height: band,
              backgroundImage: beamFill,
            }}
          />
        ) : null}
        {head > tail + 0.5
          ? wordLayer("linear-gradient(#FFFFFF, #FFFFFF)", tail, head)
          : null}
      </ScaleLayer>
      {grain ? (
        <Grain opacity={isLight ? 0.045 : 0.06} light={isLight} />
      ) : null}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  word: {
    type: "text-content",
    default: "Aligned.",
    description: "Word",
  },
  rings: {
    type: "number",
    default: 6,
    min: 0,
    max: 18,
    step: 1,
    description: "Rings",
    hiddenFromList: false,
  },
  stagger: {
    type: "number",
    default: 8,
    min: 0,
    max: 24,
    step: 1,
    description: "Lock stagger",
    hiddenFromList: false,
  },
  dotSize: {
    type: "number",
    default: 3.1,
    min: 1,
    max: 8,
    step: 0.1,
    description: "Dot size",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Geist",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","word","rings","stagger","dotSize","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  word: "Aligned.",
  rings: 6,
  stagger: 8,
  dotSize: 3.1,
  accent: "#3B5BFD",
  fontFamily: "Geist",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type RingAlignElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RingAlignBase>;

const RingAlignInner = forwardRef<
  HTMLDivElement,
  RingAlignElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RingAlign>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RingAlignBase
          {...(componentProps as unknown as ComponentProps<typeof RingAlignBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RingAlign = Interactive.withSchema({
  Component: RingAlignInner,
  componentName: "<RingAlign>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
